import {html, nothing} from 'lit';
import {msg} from '@lit/localize';
import {customElement} from 'lit/decorators.js';
import {AIUXWidgetElement, decorators} from '@servicenow/aiux-components-core';

const {category, discoverable} = decorators;

/**
 * List activity renderer for playbook cards (SDK-built widget).
 *
 * Extracts required fields from the activity props:
 *   - table / associated_table -> effectiveTable
 *   - list_title               -> heading
 *   - list_query               -> query
 *   - row_count                -> .pageSize  (property binding — the attribute
 *                                 is `pagesize`, NOT `page-size`)
 *   - ui_view                  -> view
 *   - columns                  -> columns (comma-separated column keys)
 *
 * @element playbook-list
 */
@discoverable(true)
@category('platform')
@customElement('playbook-list')
export default class PlaybookList extends AIUXWidgetElement {
  static aiContext = {
    description:
      'A list of records shown as part of the current playbook step.',
    bestFor:
      'When the user asks about the records in the current step, wants to filter, sort, or open one of them.'
  };

  static properties = {
    list_title: {type: Object},
    table: {type: Object},
    associated_table: {type: Object},
    list_query: {type: Object},
    row_count: {type: Object},
    ui_view: {type: Object},
    columns: {type: Object}
  };

  render() {
    const listTitle = this.list_title?.value;
    const effectiveTable = this.table?.value ?? this.associated_table?.value;
    const listQuery = this.list_query?.value;
    const rowCount = this.row_count?.value;
    const uiView = this.ui_view?.value;
    const columns = this.columns?.value;

    if (!effectiveTable) {
      return html`<p class="text-sm text-base-content/40 italic" role="status">
        ${msg('No list data available.')}
      </p>`;
    }

    return html`
      ${listTitle
        ? html`<h2 class="text-lg font-semibold text-base-content mb-3">
            ${listTitle}
          </h2>`
        : nothing}
      <aiux-list-connected
        table="${effectiveTable}"
        query="${listQuery || ''}"
        .pageSize="${rowCount}"
        columns="${columns || ''}"
        view="${uiView || 'default'}"
      ></aiux-list-connected>
      ></aiux-list-connected>
    `;
  }
}
